package com.android.tools.lint.checks;

import com.android.SdkConstants;
import com.android.annotations.NonNull;
import com.android.annotations.Nullable;
import com.android.resources.ResourceType;
import com.android.resources.ResourceUrl;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Context;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.JavaContext;
import com.android.tools.lint.detector.api.LayoutDetector;
import com.android.tools.lint.detector.api.Location;
import com.android.tools.lint.detector.api.ResourceEvaluator;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.SourceCodeScanner;
import com.android.tools.lint.detector.api.XmlContext;
import com.intellij.psi.PsiMethod;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.jetbrains.uast.UCallExpression;
import org.jetbrains.uast.UClass;
import org.jetbrains.uast.UExpression;
import org.jetbrains.uast.UastUtils;
import org.w3c.dom.Attr;
import org.w3c.dom.Element;
import org.w3c.dom.Node;

public class OverdrawDetector extends LayoutDetector implements SourceCodeScanner {
    private static final Implementation IMPLEMENTATION = new Implementation(
            OverdrawDetector.class,
            EnumSet.of(Scope.JAVA_FILE, Scope.RESOURCE_FILE));

    public static final Issue ISSUE = Issue.create(
            "Overdraw",
            "Overdraw: Painting regions more than once",
            "If you set a background drawable on a root view, then you should use a custom "
                    + "theme where the theme background is null. Otherwise, the theme background "
                    + "will be painted first, only to have your custom background completely cover "
                    + "it; this is called \"overdraw\".\n\n"
                    + "NOTE: This detector relies on figuring out which layouts are associated with "
                    + "which activities based on scanning the Java code, and it's currently doing "
                    + "that using an inexact pattern matching algorithm. Therefore, it can "
                    + "incorrectly conclude which activity the layout is associated with and then "
                    + "wrongly complain that a background-theme is hidden.\n\n"
                    + "If you want your custom background on multiple pages, then you should "
                    + "consider making a custom theme with your custom background and just using "
                    + "that theme instead of a root element background.\n\n"
                    + "Of course it's possible that your custom drawable is translucent and you "
                    + "want it to be mixed with the background. However, you will get better "
                    + "performance if you pre-mix the background with your drawable and use that "
                    + "resulting image or color as a custom theme background instead.",
            Category.PERFORMANCE,
            6,
            Severity.WARNING,
            IMPLEMENTATION);

    @Nullable
    private Map<String, String> mLayoutToActivity;

    @Nullable
    private Map<String, List<BackgroundInfo>> mRootBackgrounds;

    @Override
    public List<String> getApplicableMethodNames() {
        return Collections.singletonList("setContentView");
    }

    @Override
    public void visitMethodCall(@NonNull JavaContext context, @NonNull UCallExpression node,
            @NonNull PsiMethod method) {
        List<UExpression> args = node.getValueArguments();
        if (args.isEmpty()) {
            return;
        }

        String layout = getLayoutName(context, args.get(0));
        if (layout == null) {
            return;
        }

        UClass cls = UastUtils.getParentOfType(node, UClass.class);
        while (cls != null && cls.getName() == null) {
            cls = UastUtils.getParentOfType(cls, UClass.class);
        }
        if (cls == null) {
            return;
        }

        String activity = cls.getQualifiedName();
        if (activity == null) {
            return;
        }

        if (mLayoutToActivity == null) {
            mLayoutToActivity = new HashMap<>();
        }
        mLayoutToActivity.put(layout, activity);
    }

    @Override
    public Collection<String> getApplicableElements() {
        return ALL;
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        Node parent = element.getParentNode();
        if (parent != null && parent.getNodeType() == Node.ELEMENT_NODE) {
            return;
        }

        String fileName = context.file.getName();
        if (!fileName.endsWith(SdkConstants.DOT_XML)) {
            return;
        }
        String layoutName = fileName.substring(0, fileName.length() - SdkConstants.DOT_XML.length());

        Attr background = element.getAttributeNodeNS(SdkConstants.ANDROID_URI,
                SdkConstants.ATTR_BACKGROUND);
        if (background == null) {
            return;
        }

        if (mRootBackgrounds == null) {
            mRootBackgrounds = new HashMap<>();
        }
        List<BackgroundInfo> list = mRootBackgrounds.get(layoutName);
        if (list == null) {
            list = new ArrayList<>();
            mRootBackgrounds.put(layoutName, list);
        }
        list.add(new BackgroundInfo(layoutName, background.getValue(),
                context.getLocation(background)));
    }

    @Override
    public void afterCheckProject(@NonNull Context context) {
        if (mLayoutToActivity == null || mRootBackgrounds == null) {
            return;
        }

        for (Map.Entry<String, List<BackgroundInfo>> entry : mRootBackgrounds.entrySet()) {
            String activity = mLayoutToActivity.get(entry.getKey());
            if (activity == null) {
                continue;
            }

            String theme = context.getMainProject().getTheme(activity);
            if (theme == null) {
                continue;
            }

            if (!themeHasWindowBackground(context, theme)) {
                continue;
            }

            for (BackgroundInfo info : entry.getValue()) {
                String message = String.format(
                        "Possible overdraw: Root element paints background `%1$s` with a theme "
                                + "that also paints a background (inferred theme is `%2$s`)",
                        info.backgroundValue, theme);
                context.report(ISSUE, null, info.location, message);
            }
        }
    }

    private static boolean themeHasWindowBackground(@NonNull Context context,
            @NonNull String theme) {
        String styleName = theme;
        if (styleName.startsWith(SdkConstants.STYLE_PREFIX)) {
            styleName = styleName.substring(SdkConstants.STYLE_PREFIX.length());
        }

        Map<String, String> style = context.getMainProject().getStyle(styleName, true);
        if (style == null) {
            return false;
        }

        String background = style.get(SdkConstants.ANDROID_PREFIX
                + SdkConstants.ATTR_WINDOW_BACKGROUND);
        return background != null && !background.equals("@null");
    }

    @Nullable
    private static String getLayoutName(@NonNull JavaContext context,
            @NonNull UExpression expression) {
        ResourceEvaluator evaluator = new ResourceEvaluator(context.getEvaluator());
        ResourceUrl reference = evaluator.getResource(expression);
        if (reference != null && reference.type == ResourceType.LAYOUT) {
            return reference.name;
        }

        String source = expression.asSourceString();
        if (source == null) {
            return null;
        }
        source = source.replaceAll("\\s+", "");
        int index = source.lastIndexOf(".layout.");
        if (index == -1) {
            return null;
        }
        String name = source.substring(index + ".layout.".length());
        if (name.isEmpty() || name.indexOf('.') != -1) {
            return null;
        }
        return name;
    }

    private static class BackgroundInfo {
        final String layoutName;
        final String backgroundValue;
        final Location location;

        BackgroundInfo(String layoutName, String backgroundValue, Location location) {
            this.layoutName = layoutName;
            this.backgroundValue = backgroundValue;
            this.location = location;
        }
    }
}
